-- READ ONLY / POST-APPLY. Prepared only; no synthetic writes or real student seed.
begin read only;
set local search_path = pg_catalog, public;
set local timezone = 'UTC';
-- Zero mismatches required. Hashes cover columns/defaults/FK/UNIQUE/CHECK/index/trigger/policy/RLS
-- and complete function definitions. MD5 here detects catalog drift, not a security credential.
with actual as (with target(name) as (values ('essay_questions'),('essay_question_evidence'),('essay_evaluation_criteria'),('student_target_universities'),('essay_practice_sessions'),('essay_drafts'),('essay_attempts'),('essay_evaluations'),('essay_evaluation_dimensions'),('essay_improvement_items'),('essay_improvement_progress'),('essay_evaluation_evidence'),('essay_generated_rewrites'),('essay_learning_events'),('essay_ai_processing_runs'),('credit_accounts'),('credit_grants'),('essay_billing_decisions'),('credit_transactions')),
 table_objects as (
 select 'table'::text kind,t.name,
 jsonb_build_object(
 'rls',c.relrowsecurity,
 'columns',(select jsonb_agg(jsonb_build_array(a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull,pg_get_expr(ad.adbin,ad.adrelid)) order by a.attnum) from pg_attribute a left join pg_attrdef ad on ad.adrelid=a.attrelid and ad.adnum=a.attnum where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped),
 'constraints',(select jsonb_agg(jsonb_build_array(k.conname,k.contype,pg_get_constraintdef(k.oid)) order by k.conname) from pg_constraint k where k.conrelid=c.oid),
 'indexes',(select jsonb_agg(pg_get_indexdef(i.indexrelid) order by i.indexrelid::regclass::text) from pg_index i where i.indrelid=c.oid),
 'triggers',(select jsonb_agg(pg_get_triggerdef(tr.oid) order by tr.tgname) from pg_trigger tr where tr.tgrelid=c.oid and not tr.tgisinternal),
 'policies',(select jsonb_agg(jsonb_build_array(p.policyname,p.permissive,p.roles,p.cmd,p.qual,p.with_check) order by p.policyname) from pg_policies p where p.schemaname='public' and p.tablename=t.name)
 )::text definition
 from target t join pg_class c on c.oid=to_regclass('public.'||t.name)
 ), wanted_functions(schema,name) as (values ('public','essay_product_reject_update'),('public','essay_product_terminal_guard'),('public','essay_product_child_guard'),('public','essay_question_identity_guard'),('public','essay_product_progress_guard'),('public','essay_product_processing_guard'),('public','essay_product_draft_guard'),('public','essay_credit_account_guard'),('public','essay_billing_history_guard'),('essay_private','uid'),('essay_private','clock'),('essay_private','hash'),('essay_private','owner'),('essay_private','lock_job'),('essay_private','release'),('public','essay_open_session'),('public','essay_save_draft'),('public','essay_submit_attempt'),('public','essay_request_evaluation'),('public','essay_request_rewrite'),('public','essay_claim'),('essay_private','fence'),('public','essay_timeout'),('public','essay_finalize_success'),('public','essay_finalize_failure'),('public','essay_reconcile'),('public','essay_refund'),('public','essay_erase')),
 function_objects as (select 'function'::text kind,n.nspname||'.'||p.proname||'('||pg_get_function_identity_arguments(p.oid)||')' name,pg_get_functiondef(p.oid) definition from pg_proc p join pg_namespace n on n.oid=p.pronamespace join wanted_functions f on (f.schema,f.name)=(n.nspname,p.proname)),
 objects as (select * from table_objects union all select * from function_objects)
 select kind,name,md5(definition) definition_hash from objects order by kind,name), expected(kind,name,definition_hash) as (values ('function','essay_private.clock()','6ba208957796c86031be7f150988ee24'),('function','essay_private.fence(p_evaluation uuid, p_run uuid, p_token uuid, p_rewrite uuid)','3960cea03c6ccdefac9289187fa3b0aa'),('function','essay_private.hash(p_text text)','d21fb8743e7a5039a26ecebd1b5a92e7'),('function','essay_private.lock_job(p_evaluation uuid)','02853d30a8ddccee78ee7f7e0bbfd4f1'),('function','essay_private.owner(p_session uuid)','2b90f025f8ae19d53cb653d2c4868422'),('function','essay_private.release(p_evaluation uuid)','e019bddf2af1d0a95f28e7e318112031'),('function','essay_private.uid()','b2d988f9bc5bb6e7b742c7821db7a7a5'),('function','public.essay_billing_history_guard()','367d2b0957d708ffd408890e55ab33b3'),('function','public.essay_claim(p_evaluation uuid, p_rewrite uuid)','69bd6e34605f65cf40140673a77d4a49'),('function','public.essay_credit_account_guard()','1466dc181f4100782035c4c7934344f9'),('function','public.essay_erase(p_session uuid)','7e9f0a1996431f1c010ffec20ad81d02'),('function','public.essay_finalize_failure(p_evaluation uuid, p_run uuid, p_token uuid, p_rewrite uuid)','1b8c08e315725e62c909df242c5f2768'),('function','public.essay_finalize_success(p_evaluation uuid, p_run uuid, p_token uuid, p_output jsonb, p_rewrite uuid)','1317ab408ccb208041f01955b958a109'),('function','public.essay_open_session(p_id uuid, p_question uuid)','724c4a8a6e8228e4996441ef4c274fed'),('function','public.essay_product_child_guard()','ae43c0e2d3a1a15cbc3ae3f79e14f885'),('function','public.essay_product_draft_guard()','178355a7378a6970676ffa1af2acda4c'),('function','public.essay_product_processing_guard()','a7559f3135904f27b2e68fe2a75c2fc8'),('function','public.essay_product_progress_guard()','3f0dd98c4b05ebb5faaf42743dd63e45'),('function','public.essay_product_reject_update()','be7868ad49936437d52a7fe0c1366cc7'),('function','public.essay_product_terminal_guard()','dc40b178939b1fdc119c007db28edf8a'),('function','public.essay_question_identity_guard()','5b634bcca516ead399ffd38eee569461'),('function','public.essay_reconcile(p_evaluation uuid, p_rewrite uuid)','1f2a603f781b2a8898c72d9610606ba4'),('function','public.essay_refund(p_consume uuid, p_key text, p_amount integer)','5f82b9cb5cd645e8e1d084aebf4a36c6'),('function','public.essay_request_evaluation(p_attempt uuid, p_key uuid, p_regime text)','ac0832ffb7e2ac96d75cc76ff09cab8e'),('function','public.essay_request_rewrite(p_evaluation uuid)','afc5b871a8f8c647bbfb734505b6ebec'),('function','public.essay_save_draft(p_session uuid, p_revision bigint, p_body text, p_device text, p_mode text, p_active_seconds integer)','b85e042902169e1cd99d107206ce0976'),('function','public.essay_submit_attempt(p_session uuid, p_revision bigint, p_key uuid, p_body_hash text)','93d9a0ef45a58ca5e037b062a809d661'),('function','public.essay_timeout(p_evaluation uuid, p_run uuid, p_token uuid, p_rewrite uuid)','b5b74d44275a5dc881207e2c0ec4fb13'),('table','credit_accounts','065f9ec7d3332691b28295654cd1c962'),('table','credit_grants','368fb4eeeaf3ceedcb5ef35eb11f7339'),('table','credit_transactions','0fe5f8c8f2277cc4ca17ce7dec875058'),('table','essay_ai_processing_runs','205ac0d67fa18c80c697ebcfd838e021'),('table','essay_attempts','77d4b71131025686fcb9d7d29dd9f8cc'),('table','essay_billing_decisions','3b8291374232f2a536362f2b6d0225d8'),('table','essay_drafts','6978d419d8dcf2748778b92497eb9142'),('table','essay_evaluation_criteria','373de96a82d2ee3388f4c9b1d35123f9'),('table','essay_evaluation_dimensions','6e13296ebd64b937592a1fc53eaea9d1'),('table','essay_evaluation_evidence','716a71fb768d6cb6792fa578d5da1144'),('table','essay_evaluations','9b29f6e6b69a8af75fb84ffba53103f7'),('table','essay_generated_rewrites','2103c217cb1fc3eadb72430b937e8e0b'),('table','essay_improvement_items','bf7fce080e57d8cffb8a4f66fff77897'),('table','essay_improvement_progress','925f48c83dd633728a3d945b9e6275d0'),('table','essay_learning_events','19cf4b2e3d4ca9f0875141cf2f67591d'),('table','essay_practice_sessions','c782690219b3654faf5a3b6d3650d32b'),('table','essay_question_evidence','1d13692345fe709bb983f7d05cf97317'),('table','essay_questions','0951e523947ad74e72d66570945edad7'),('table','student_target_universities','ad63e7bd37e03bec052fee85089a6a84'))
select coalesce(e.kind,a.kind) kind,coalesce(e.name,a.name) name,e.definition_hash is not distinct from a.definition_hash as definition_matches
from expected e full join actual a using(kind,name) order by 1,2;
select count(*)=19 as all_19_present,bool_and(relrowsecurity) as all_rls_enabled from pg_class where oid in (select to_regclass('public.'||name) from unnest(array['essay_questions','essay_question_evidence','essay_evaluation_criteria','student_target_universities','essay_practice_sessions','essay_drafts','essay_attempts','essay_evaluations','essay_evaluation_dimensions','essay_improvement_items','essay_improvement_progress','essay_evaluation_evidence','essay_generated_rewrites','essay_learning_events','essay_ai_processing_runs','credit_accounts','credit_grants','essay_billing_decisions','credit_transactions']) name);
select t,c,exists(select 1 from information_schema.columns where table_schema='public' and table_name=t and column_name=c) as additive_column_present from (values
('essay_attempts','submission_request_hash'),('essay_evaluations','input_snapshot'),('essay_ai_processing_runs','lease_token'),('essay_ai_processing_runs','lease_expires_at')) cols(t,c);
select name,(xpath('/table/row/n/text()',query_to_xml(format('select count(*) n from public.%I',name),false,false,'')))[1]::text::bigint as initial_count_should_be_zero from unnest(array['essay_questions','essay_question_evidence','essay_evaluation_criteria','student_target_universities','essay_practice_sessions','essay_drafts','essay_attempts','essay_evaluations','essay_evaluation_dimensions','essay_improvement_items','essay_improvement_progress','essay_evaluation_evidence','essay_generated_rewrites','essay_learning_events','essay_ai_processing_runs','credit_accounts','credit_grants','essay_billing_decisions','credit_transactions']) name;
-- Orphan counts for every new-table FK; no answer/identity rows returned.
with f as (
 select k.oid,k.conname,k.conrelid,k.confrelid,
 string_agg(format('a.%I=b.%I',a.attname,b.attname),' and ' order by cols.ord) join_clause,
 string_agg(format('a.%I is not null',a.attname),' and ' order by cols.ord) nonnull_clause
 from pg_constraint k cross join lateral unnest(k.conkey,k.confkey) with ordinality cols(a,b,ord)
 join pg_attribute a on a.attrelid=k.conrelid and a.attnum=cols.a
 join pg_attribute b on b.attrelid=k.confrelid and b.attnum=cols.b
 where k.contype='f' and k.conrelid in (select to_regclass('public.'||name) from unnest(array['essay_questions','essay_question_evidence','essay_evaluation_criteria','student_target_universities','essay_practice_sessions','essay_drafts','essay_attempts','essay_evaluations','essay_evaluation_dimensions','essay_improvement_items','essay_improvement_progress','essay_evaluation_evidence','essay_generated_rewrites','essay_learning_events','essay_ai_processing_runs','credit_accounts','credit_grants','essay_billing_decisions','credit_transactions']) name)
 group by k.oid,k.conname,k.conrelid,k.confrelid
)
select conrelid::regclass::text relation,conname,
 (xpath('/table/row/n/text()',query_to_xml(format('select count(*) n from %s a where %s and not exists(select 1 from %s b where %s)',conrelid::regclass,nonnull_clause,confrelid::regclass,join_clause),false,false,'')))[1]::text::bigint orphan_count from f order by 1,2;
-- Direct client fact writes must be false. Draft editing remains explicitly allowed by design.
select name,role,privilege,has_table_privilege(role,'public.'||name,privilege) as granted
from unnest(array['essay_questions','essay_question_evidence','essay_evaluation_criteria','student_target_universities','essay_practice_sessions','essay_drafts','essay_attempts','essay_evaluations','essay_evaluation_dimensions','essay_improvement_items','essay_improvement_progress','essay_evaluation_evidence','essay_generated_rewrites','essay_learning_events','essay_ai_processing_runs','credit_accounts','credit_grants','essay_billing_decisions','credit_transactions']) name cross join unnest(array['anon','authenticated','essay_worker','essay_finance']) role cross join unnest(array['SELECT','INSERT','UPDATE','DELETE']) privilege order by 1,2,3;
-- Functions: compare EXECUTE allowlist to package README; security definer owners/search paths included.
with wanted(schema,name) as (values ('public','essay_product_reject_update'),('public','essay_product_terminal_guard'),('public','essay_product_child_guard'),('public','essay_question_identity_guard'),('public','essay_product_progress_guard'),('public','essay_product_processing_guard'),('public','essay_product_draft_guard'),('public','essay_credit_account_guard'),('public','essay_billing_history_guard'),('essay_private','uid'),('essay_private','clock'),('essay_private','hash'),('essay_private','owner'),('essay_private','lock_job'),('essay_private','release'),('public','essay_open_session'),('public','essay_save_draft'),('public','essay_submit_attempt'),('public','essay_request_evaluation'),('public','essay_request_rewrite'),('public','essay_claim'),('essay_private','fence'),('public','essay_timeout'),('public','essay_finalize_success'),('public','essay_finalize_failure'),('public','essay_reconcile'),('public','essay_refund'),('public','essay_erase'))
select n.nspname,p.proname,pg_get_function_identity_arguments(p.oid) arguments,
 pg_get_userbyid(p.proowner) owner,p.prosecdef,p.proconfig,role,has_function_privilege(role,p.oid,'EXECUTE') executable
from pg_proc p join pg_namespace n on n.oid=p.pronamespace join wanted w on (w.schema,w.name)=(n.nspname,p.proname)
cross join unnest(array['anon','authenticated','service_role','essay_worker','essay_finance']) role order by 1,2,7;
select rolname,rolcanlogin,rolsuper,rolbypassrls from pg_roles where rolname in ('essay_executor','essay_worker','essay_finance');
-- B2 contract: zero local superuser-created memberships OR exact managed ADMIN-only rows.
-- postgres remains a trusted administrator; ADMIN permits explicit regrant, not a security sandbox.
select parent.rolname granted_role,member.rolname member_role,grantor.rolname grantor_role,
 a.admin_option,a.inherit_option,a.set_option,
 pg_has_role(member.oid,parent.oid,'USAGE') as effective_inherit,
 pg_has_role(member.oid,parent.oid,'SET') as effective_set
from pg_auth_members a join pg_roles parent on parent.oid=a.roleid
join pg_roles member on member.oid=a.member join pg_roles grantor on grantor.oid=a.grantor
where parent.rolname in ('essay_executor','essay_worker','essay_finance');
select has_schema_privilege('essay_executor','public','CREATE') as executor_public_create_must_be_false,
 has_schema_privilege('essay_executor','essay_private','CREATE') as executor_private_create_must_be_false;
-- Same values as the saved PRE-APPLY snapshot required; no hard-coded Production row counts.
select name,
 (xpath('/table/row/n/text()',query_to_xml(format('select count(*) as n from public.%I',name),false,false,'')))[1]::text::bigint row_count,
 (xpath('/table/row/h/text()',query_to_xml(format('select md5(coalesce(string_agg(row_to_json(t)::text, chr(10) order by row_to_json(t)::text),'''')) as h from public.%I t',name),false,false,'')))[1]::text content_fingerprint
 from (values ('universities'),('essay_exams'),('essay_exam_resources'),('resources')) t(name) order by name;
select case when to_regclass('supabase_migrations.schema_migrations') is not null then
 query_to_xml('select version from supabase_migrations.schema_migrations order by version',false,false,'') end as applied_versions;
rollback;
